import copy

def rotate_matrix(matrix):
    n = len(matrix)
    # Create a new matrix to hold the rotated result
    rotated_matrix = [[0] * n for _ in range(n)]

    # Copy each row of the original matrix into the rotated matrix in reverse order
    for i in range(n):
        for j in range(n):
            rotated_matrix[j][n-i-1] = matrix[i][j]

    return rotated_matrix

# Example usage:
data = {
    "m": [
        [1, 2],
        [3, 4]
    ]
}
result = rotate_matrix(data["m"])
print(result)  # Output: [[3, 1], [4, 2]]

